INSERT INTO venues (slug, name, genre, price, event_date, venue, location, image, summary, lineup, description)
VALUES
  ('velvet-room', 'Velvet Room', 'Indie Rock', '$18', 'Friday • 8:30 PM', 'East Market Hall', 'Riverside', 'https://images.unsplash.com/photo-1516280440614-37939bbacd81?auto=format&fit=crop&w=900&q=80', 'A moody listening room with intimate sets and a loyal local crowd.', 'Midnight Echo, The Lanterns, Clover Club', 'The Velvet Room is a hidden gem for fans of indie and alternative music. The room is dimly lit, the sound is crisp, and every set feels like a neighborhood secret. It is the kind of venue where you can discover your next favorite band before they hit the big stage.'),
  ('harbor-stage', 'Harbor Stage', 'Jazz', '$15', 'Saturday • 7:00 PM', 'Waterfront Pavilion', 'Harbor District', 'https://images.unsplash.com/photo-1501612780327-45045538702b?auto=format&fit=crop&w=900&q=80', 'A waterfront venue hosting smooth jazz sets and sunset cocktails.', 'Northline Quartet, June Avenue, The Green Room Trio', 'Harbor Stage brings a relaxed, upscale feel to live music with sweeping views of the bay and carefully curated jazz sessions. It is the perfect place for a date night or a low-key evening with friends who appreciate improvisation, classic standards, and jazz fusion.'),
  ('neon-loft', 'Neon Loft', 'Electronic', '$22', 'Thursday • 10:00 PM', 'Warehouse 9', 'Downtown Arts District', 'https://images.unsplash.com/photo-1492684223066-81342ee5ff30?auto=format&fit=crop&w=900&q=80', 'A late-night dance floor for house, synthwave, and futuristic soundscapes.', 'Kite Runner, Aster Vale, Dial Tone', 'Neon Loft feels like stepping into a music video from the future. Floor-to-ceiling lights, bass-heavy sound systems, and a rotating set of electronic artists create an energizing night out for dancers and festival lovers alike. It is loud, immersive, and built for midnight energy.'),
  ('cedar-cafe', 'Cedar & Co. Cafe', 'Acoustic', '$10', 'Sunday • 5:30 PM', 'Cedar & Co. Cafe', 'Old Town', 'https://images.unsplash.com/photo-1525201548942-d8732f6617a0?auto=format&fit=crop&w=900&q=80', 'Coffeehouse sessions with acoustic folk, singer-songwriters, and open mic nights.', 'Mara Wells, The Cedar Songwriters, Open Mic Hour', 'Cedar & Co. Cafe is where students and locals go for low-pressure music nights. The intimate setup encourages conversation and connection, and the acoustic sets feel personal and warm. It is the community heart of the neighborhood and a favorite for relaxed gatherings.'),
  ('skyline-amphitheater', 'Skyline Amphitheater', 'Festival', '$35', 'Saturday • 6:45 PM', 'Hilltop Grounds', 'North Ridge', 'https://images.unsplash.com/photo-1501386761578-eac5c94b800a?auto=format&fit=crop&w=900&q=80', 'An open-air festival stage with headline acts, food trucks, and sunset views.', 'Sunset Parade, City Bloom, Afterglow Collective', 'Skyline Amphitheater turns live music into a full community event with food stalls, lawn seating, and panoramic city views. It is ideal for large groups, festival energy, and discovering new artists while enjoying a warm evening outside. The experience feels celebratory from the first chord to the final encore.'),
  ('paper-bell', 'Paper Bell Studio', 'Folk', '$12', 'Wednesday • 7:15 PM', 'Paper Bell Loft', 'North Loop', 'https://images.unsplash.com/photo-1507838153414-b4b713384a76?auto=format&fit=crop&w=900&q=80', 'A creative studio space for folk artists, storytellers, and warm acoustic sets.', 'Hollow Pines, Rowan Vale, Lark & Stone', 'Paper Bell Studio blends live music with the feeling of an artist retreat. The room is compact, the sets feel intimate, and the audience is often made up of devoted fans and curious newcomers alike. It is a favorite stop for folk lovers seeking heartfelt songwriting and community energy.')
